-- Guestbook without user accounts.
-- Drops the old account-based tables (users, server-side achievements, comments linked to a user)
-- and recreates the comment table: each message now carries its author's pseudo and the SHA-256
-- hash of a random password generated by the visitor's browser, used to edit/delete it for 7 days.
-- Existing messages are intentionally discarded.

DROP TABLE IF EXISTS achievement;
DROP TABLE IF EXISTS Achievement;
DROP TABLE IF EXISTS comment;
DROP TABLE IF EXISTS Comment;
DROP TABLE IF EXISTS user;
DROP TABLE IF EXISTS User;

CREATE TABLE comment (
    id            BIGINT       NOT NULL AUTO_INCREMENT,
    pseudo        VARCHAR(20)  NOT NULL,
    comment       VARCHAR(250) NOT NULL,
    coordinate_x  INT          NOT NULL,
    coordinate_y  INT          NOT NULL,
    created_at    DATETIME(6)  NOT NULL,
    password_hash VARCHAR(64)  NOT NULL,
    PRIMARY KEY (id),
    INDEX idx_comment_coordinates (coordinate_x, coordinate_y)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;
